function q(string $sql, array $params=[]): PDOStatement { global $db; $s=$db->prepare($sql); $s->execute($params); return $s; }
function e(?string $v): string { return htmlspecialchars($v ?? '', ENT_QUOTES, 'UTF-8'); }
function containsCyrillic(mixed $value): bool { if (is_array($value)) { foreach ($value as $item) if (containsCyrillic($item)) return true; return false; } return is_string($value) && preg_match('/\p{Cyrillic}/u', $value) === 1; }
function redirect(string $page): never { header('Location: ?page='.$page); exit; }
