  if($action==='add_access_request'){ $existing=isset($_POST['existing_user']); $userName=trim($_POST['manual_user_name']??''); $userEmail=trim($_POST['manual_user_email']??''); $manualTeamName=trim($_POST['manual_team_name']??''); $listedUserName=trim($_POST['user_name']??''); $knownUser=$existing ? null : q('SELECT id FROM newcomers WHERE full_name=? ORDER BY id DESC LIMIT 1',[$listedUserName])->fetch(PDO::FETCH_ASSOC); $manualTeam=$existing && $manualTeamName!=='' ? q('SELECT id FROM teams WHERE name=?',[$manualTeamName])->fetch(PDO::FETCH_ASSOC) : null; $newcomerId=$existing ? null : (int)($knownUser['id']??0); if($existing && ($userName==='' || $userEmail==='')){$_SESSION['flash']='User and email are required for an existing user.';redirect($page);} if($existing && $manualTeamName!=='' && !$manualTeam){$_SESSION['flash']='Please select a Team from the suggested list.';redirect($page);} if(!$existing && !$newcomerId){$_SESSION['flash']='Please select a User from the suggested list.';redirect($page);} q('INSERT INTO access_requests(newcomer_id,manual_user_name,manual_user_email,manual_team_id,application_id,mirror_id,justification) VALUES(?,?,?,?,?,?,?)',[$newcomerId,$existing?$userName:null,$existing?$userEmail:null,$manualTeam ? (int)$manualTeam['id'] : null,(int)$_POST['application_id'],trim($_POST['mirror_id']),trim($_POST['justification'])]);}
  if($action==='add_access_requests_batch'){ $existing=isset($_POST['existing_user']); $userName=trim($_POST['manual_user_name']??''); $userEmail=trim($_POST['manual_user_email']??''); $manager=trim($_POST['manager']??''); $manualTeamName=trim($_POST['manual_team_name']??''); $listedUserName=trim($_POST['user_name']??''); $knownUser=$existing ? null : q('SELECT id FROM newcomers WHERE full_name=? ORDER BY id DESC LIMIT 1',[$listedUserName])->fetch(PDO::FETCH_ASSOC); $manualTeam=$existing ? q('SELECT id FROM teams WHERE name=?',[$manualTeamName])->fetch(PDO::FETCH_ASSOC) : null; $newcomerId=$existing ? null : (int)($knownUser['id']??0); $requests=json_decode($_POST['requests_json']??'',true); if($existing && ($userName==='' || $userEmail==='')){$_SESSION['flash']='User name and User Primark account are required.';redirect($page);} if($existing && !$manualTeam){$_SESSION['flash']='Please select a Team from the suggested list.';redirect($page);} if(!$existing && !$newcomerId){$_SESSION['flash']='Please select a User from the suggested list.';redirect($page);} if(!is_array($requests)||!count($requests)){$_SESSION['flash']='Select at least one Application.';redirect($page);} $applicationIds=[]; foreach($requests as $request){$appId=(int)($request['application_id']??0); if(!$appId||isset($applicationIds[$appId])){$_SESSION['flash']='Each Application can be selected only once.';redirect($page);} $applicationIds[$appId]=true;} $available=q('SELECT COUNT(*) FROM applications WHERE enabled=1 AND id IN ('.implode(',',array_map('intval',array_keys($applicationIds))).')')->fetchColumn(); if((int)$available!==count($applicationIds)){$_SESSION['flash']='One or more selected Applications are not available.';redirect($page);} $existingIds=$newcomerId ? q("SELECT DISTINCT application_id FROM access_requests WHERE newcomer_id=? AND COALESCE(approval_status,'')<>'Revoked'",[$newcomerId])->fetchAll(PDO::FETCH_COLUMN) : q("SELECT DISTINCT ar.application_id FROM access_requests ar LEFT JOIN newcomers n ON n.id=ar.newcomer_id WHERE LOWER(COALESCE(NULLIF(ar.manual_user_email,''),n.email,''))=LOWER(?) AND COALESCE(ar.approval_status,'')<>'Revoked'",[$userEmail])->fetchAll(PDO::FETCH_COLUMN); if(array_intersect(array_map('intval',array_keys($applicationIds)),array_map('intval',$existingIds))){$_SESSION['flash']='One or more selected Applications already have an active access request for this user.';redirect($page);} $db->beginTransaction(); try{$insert=$db->prepare('INSERT INTO access_requests(newcomer_id,manual_user_name,manual_user_email,manual_team_id,manager,application_id,mirror_id,justification) VALUES(?,?,?,?,?,?,?,?)'); foreach($requests as $request)$insert->execute([$newcomerId,$existing?$userName:null,$existing?$userEmail:null,$manualTeam ? (int)$manualTeam['id'] : null,$manager,(int)$request['application_id'],trim((string)($request['mirror_id']??'')),trim((string)($request['justification']??''))]); if($newcomerId){q("UPDATE newcomers SET status='App access requested' WHERE id=? AND status<>'Complete'",[$newcomerId]);}else{q("UPDATE newcomers SET status='App access requested' WHERE status<>'Complete' AND (LOWER(full_name)=LOWER(?) OR LOWER(COALESCE(email,''))=LOWER(?))",[$userName,$userEmail]);} $db->commit();}catch(Throwable $error){$db->rollBack();throw $error;}}
