  if($action==='update_record'){ $table=$_POST['table']??''; if($table==='teams')q('UPDATE teams SET name=?,lead=?,primark_manager=?,notes=? WHERE id=?',[trim($_POST['name']),trim($_POST['lead']),trim($_POST['primark_manager']),trim($_POST['notes']),(int)$_POST['id']]); if($table==='applications')q('UPDATE applications SET name=?,approver=?,backup_approver=?,levy_copy=?,ad_group=?,comment=?,enabled=? WHERE id=?',[trim($_POST['name']),trim($_POST['approver']),trim($_POST['backup_approver']),isset($_POST['levy_copy'])?1:0,trim($_POST['ad_group']),trim($_POST['comment']),isset($_POST['enabled'])?1:0,(int)$_POST['id']]); if($table==='access_rules')q('UPDATE access_rules SET team_id=?,application_id=?,mirror_id=?,justification=? WHERE id=?',[(int)$_POST['team_id'],(int)$_POST['application_id'],trim($_POST['mirror_id']),trim($_POST['justification']),(int)$_POST['id']]); if($table==='newcomers') { updateNewcomer($_POST); if(isset($_POST['open_access_request'])) { header('Location: ?page=requests&open_request=1&newcomer_id='.(int)$_POST['id']); exit; } } if($table==='access_requests'){ if(isset($_POST['remove_revoked_request'])) q("DELETE FROM access_requests WHERE id=? AND approval_status='Revoked'",[(int)$_POST['id']]); else { $requestedDateTime=trim($_POST['requested_datetime']??''); $createdAt=$requestedDateTime===''?null:str_replace('T',' ',$requestedDateTime).':00'; q('UPDATE access_requests SET approval_status=?,snow_ticket=?,snow_ticket_url=?,justification=?,access_granted=?,user_confirmation=?,comments=?,created_at=COALESCE(?,created_at) WHERE id=?',[trim($_POST['approval_status']),trim($_POST['snow_ticket']),trim($_POST['snow_ticket_url']),trim($_POST['justification']),isset($_POST['access_granted'])?1:0,isset($_POST['user_confirmation'])?1:0,trim($_POST['comments']),$createdAt,(int)$_POST['id']]); } } }
