function options(string $table,string $label='name'): string { $rows=q("SELECT id,$label FROM $table ORDER BY $label")->fetchAll(PDO::FETCH_ASSOC); $o=''; foreach($rows as $r)$o.='<option value="'.$r['id'].'">'.e($r[$label]).'</option>'; return $o; }
function statusBadge(string $s): string {$c=in_array($s,['Approved','Complete'],true)?'green':($s==='Rejected'?'red':($s==='Revoked'?'gray':($s==='Not requested'?'pink':($s==='In progress'?'':'amber')))); return '<span class="badge '.$c.'">'.e($s).'</span>';}
